insert into public.product_categories (name, slug, sort_order) values
('Kitchen Accessories', 'kitchen-accessories', 10), ('Wardrobe Accessories', 'wardrobe-accessories', 20), ('Decor Products', 'decor-products', 30), ('Smart Products', 'smart-products', 40)
on conflict (slug) do nothing;
insert into public.product_categories (name, slug, parent_id, sort_order)
select child.name, child.slug, parent.id, child.sort_order from (values
('Pantry Solutions','pantry-solutions','kitchen-accessories',10),('Pullout Solutions','pullout-solutions','kitchen-accessories',20),('Corner Solutions','corner-solutions','kitchen-accessories',30),('Wicker Baskets','wicker-baskets','kitchen-accessories',40),('Rolling Shutters','rolling-shutters','kitchen-accessories',50),('Dish Racks','dish-racks','kitchen-accessories',60),('Lift Up Solutions','lift-up-solutions','kitchen-accessories',70),('Cabinet Hinges','cabinet-hinges','kitchen-accessories',80),('Tandem Box','tandem-box','kitchen-accessories',90),('Bins','bins','kitchen-accessories',100),('Aluminium Profiles','aluminium-profiles','kitchen-accessories',110),('Hardware Fittings','hardware-fittings','kitchen-accessories',120),('Trouser Racks','trouser-racks','wardrobe-accessories',10),('Shoe Racks','shoe-racks','wardrobe-accessories',20),('Wardrobe Lifters','wardrobe-lifters','wardrobe-accessories',30),('Wardrobe Baskets','wardrobe-baskets','wardrobe-accessories',40),('Hangers','hangers','wardrobe-accessories',50),('Smart Furniture','smart-furniture','smart-products',10),('Smart Kitchen / Waterfall Sinks','smart-kitchen-waterfall-sinks','smart-products',20)
) as child(name,slug,parent_slug,sort_order) join public.product_categories parent on parent.slug = child.parent_slug on conflict (slug) do nothing;
